<template><div class="portal-page"><header><h1>Centro de ayuda</h1><p>Consulta nuestros artículos y guías</p></header><div class="card"><div class="toolbar"><input v-model="search" type="text" placeholder="Buscar artículos..." @input="debounceFetch"></div><div v-if="loading" class="state">Cargando artículos...</div><template v-else><div v-if="!articles.length" class="state">No se encontraron artículos</div><div v-else class="content"><template v-if="search.trim()"><ul><li v-for="a in articles" :key="a.id"><router-link :to="`/help/${a.slug}`"><strong>{{a.title}}</strong><small v-if="a.group">{{a.group.name}}</small></router-link></li></ul></template><template v-else><section v-for="g in nonEmptyGroups" :key="g.id"><h2>{{g.name}}</h2><p v-if="g.description">{{g.description}}</p><ul><li v-for="a in articlesByGroup[g.id]" :key="a.id"><router-link :to="`/help/${a.slug}`">{{a.title}}</router-link></li></ul></section><section v-if="ungrouped.length"><h2>Otros artículos</h2><ul><li v-for="a in ungrouped" :key="a.id"><router-link :to="`/help/${a.slug}`">{{a.title}}</router-link></li></ul></section></template></div></template></div></div></template><script>export default{data(){return{groups:[],articles:[],search:'',loading:false,debounce:null}},computed:{articlesByGroup(){const m={};for(const a of this.articles){const id=a.knowledge_base_article_group_id;if(!id)continue;(m[id]||(m[id]=[])).push(a)}return m},nonEmptyGroups(){return this.groups.filter(g=>(this.articlesByGroup[g.id]||[]).length)},ungrouped(){return this.articles.filter(a=>!a.knowledge_base_article_group_id)}},mounted(){this.fetch()},methods:{async fetch(){this.loading=true;try{const{data}=await axios.get('/portal/knowledge-base',{params:{q:this.search||undefined}});this.groups=data.groups||[];this.articles=data.articles||[]}catch(_){}this.loading=false},debounceFetch(){clearTimeout(this.debounce);this.debounce=setTimeout(()=>this.fetch(),300)}}}</script><style scoped>header{margin-bottom:1.25rem}h1{margin:0}header p{margin:.2rem 0 0;color:var(--pc-text-muted)}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);overflow:hidden}.toolbar{padding:1rem;border-bottom:1px solid var(--pc-border)}.toolbar input{width:100%;padding:.65rem;border:1px solid var(--pc-border-strong);border-radius:8px;box-sizing:border-box}.state{padding:3rem;text-align:center;color:var(--pc-text-muted)}.content{padding:1.25rem}.content section{padding-bottom:1rem;border-bottom:1px solid var(--pc-border)}.content ul{list-style:none;padding:0}.content li a{display:flex;flex-direction:column;padding:.65rem;text-decoration:none;color:var(--pc-text);border-radius:8px}.content li a:hover{background:var(--pc-surface-alt);color:var(--pc-primary)}small{color:var(--pc-text-muted);margin-top:.2rem}</style>